-- --- assert -------------------------------------------------------------------
do $$
declare n int;
begin
  -- The sixth naivedya offering reaches both poojas, in all three scripts.
  select count(*) into n from public.pooja_steps
   where step_title_en like 'Naivedyam%'
     and mantra_sanskrit like '%' || 'ब्रह्मणे स्वाहा' || '%'
     and mantra_tamil like '%' || 'ப்ரஹ்மணே ஸ்வாஹா' || '%'
     and mantra_translit like '%' || 'brahmaṇe svāhā' || '%';
  if n <> 2 then raise exception 'expected 2 naivedyam steps with brahmane svaha, found %', n; end if;
  -- and the evening form is stored beside it.
  select count(*) into n from public.pooja_steps
   where step_title_en like 'Naivedyam%' and variant_mantra_sanskrit is not null;
  if n <> 2 then raise exception 'expected 2 naivedyam steps with an evening variant, found %', n; end if;
  -- The prana offerings appear ONCE, not twice. Five "svaha" for the pranas
  -- plus one for brahman is six; the duplicated row had eleven.
  select count(*) into n from public.pooja_steps
   where step_title_en like 'Naivedyam%'
     and (length(mantra_sanskrit) - length(replace(mantra_sanskrit, 'स्वाहा', ''))) / length('स्वाहा') <> 6;
  if n > 0 then raise exception '% naivedyam steps do not have exactly 6 svaha offerings', n; end if;
  -- The mantra pushpam is a mantra pushpam.
  select count(*) into n from public.pooja_steps
   where step_title_en = 'Mantra Pushpam & Namaskaram'
     and mantra_sanskrit like '%योऽपां पुष्पं वेद%';
  if n <> 1 then raise exception 'the Vedic mantra pushpam is not in place'; end if;
  -- and it was not stacked twice by a re-run.
  select count(*) into n from public.pooja_steps
   where (length(mantra_sanskrit) - length(replace(mantra_sanskrit, 'योऽपां पुष्पं वेद', ''))) > length('योऽपां पुष्पं वेद');
  if n > 0 then raise exception 'the mantra pushpam was inserted more than once'; end if;
  -- The sankalpam keeps its slot and now opens with the resolve.
  select count(*) into n from public.pooja_steps
   where pooja_id = 'ganesha_standard' and step_title_en = 'Sankalpam'
     and mantra_sanskrit like 'मम उपात्त%'
     and mantra_sanskrit like '%[DYNAMIC_PANCHANGAM_DATA]%'
     and mantra_tamil like '%[DYNAMIC_PANCHANGAM_DATA]%'
     and mantra_translit like '%[DYNAMIC_PANCHANGAM_DATA]%';
  if n <> 1 then raise exception 'the Ganesha sankalpam is not in the expected shape'; end if;
  -- The invocation has an object again.
  select count(*) into n from public.pooja_steps
   where pooja_id = 'ganesha_standard' and step_title_en = 'Avahanam & Asanam'
     and mantra_sanskrit like '%मृत्तिकाबिम्बे%';
  if n <> 1 then raise exception 'asmin mrttikabimbe is missing from the avahanam'; end if;
  -- Nothing anywhere is an unreviewed draft or a truncation.
  select count(*) into n from public.pooja_steps
   where source_ref is null or source_ref like '%pending vaidika review%'
      or position('...' in coalesce(mantra_sanskrit, '')) > 0;
  if n > 0 then raise exception '% steps are unsourced or truncated', n; end if;
end $$;


